 const nativeViews=[{id:'flow',diagramType:'workflow',service:'service',source:'source',anchor:{locator:'note',quote:sourceText},spec:{schema_version:2,diagram_type:'workflow',meta:{title:'Catalog flow',output:'flow.html'},lanes:[{id:'lane',label:'Curator'}],nodes:[{id:'node',lane:'lane',col:0,type:'frontend',label:'Create'}],edges:[]},laneBindings:[{lane:'lane',role:'curator'}],bindings:[{node:'node',object:'create',type:'activity'}]}];
 nativeViews[0].spec.lanes.push({id:'reviewLane',label:'Reviewer'},{id:'systemLane',label:'Indexer'});nativeViews[0].laneBindings.push({lane:'reviewLane',role:'reviewer'},{lane:'systemLane',role:'indexer'});for(const [id,lane,activity] of [['nodeRework','lane','rework'],['nodeReview','reviewLane','review'],['nodePublish','reviewLane','publish'],['nodeIndex','systemLane','automate']]){nativeViews[0].spec.nodes.push({id,lane,col:nativeViews[0].spec.nodes.length,type:'frontend',label:activity});nativeViews[0].bindings.push({node:id,object:activity,type:'activity'});}
 profile.productDocument.services[0].workflows=[{view:'flow',caption:'Catalog workflow'}];
