 assert.match(curator,/^\s*<a id="curatorChapter"><\/a>\s*\*\*Role workflow\*\*\s*!\[Curator workflow\]\(assets\/flow.svg\)\s*#### Responsibilities and scope/);assert.match(curator,/Entry \/ login: Sign in to the catalog/);assert.match(curator,/Dashboard \/ assigned tasks: Open assigned drafts/);assert.match(curator,/Enter Service: Enter the catalog/);assert.match(curator,/Ordered tasks: Create record → Request revision/);assert.match(curator,/Handoff \/ outcome: Send the draft for review/);assert.match(curator,/##### Describe an object[\s\S]*As Curator/);assert.match(curator,/##### Request revision/);assert.doesNotMatch(curator,/##### Review an object|Flag absent names/);
 assert.match(reviewer,/##### Review an object[\s\S]*As Reviewer/);assert.match(reviewer,/##### Publish an object/);assert.match(reviewer,/Flag absent names/);assert.doesNotMatch(reviewer,/Explain an empty description/);assert.match(system,/Automated sequence: Index an object/);assert.match(system,/Automated task; no human page is modeled/);assert.doesNotMatch(system,/login|Dashboard/);assert.match(system,/A complete record is indexed → A search entry exists/);
 assert.match(curator,/!\[Editor concept\]\(assets\/editor.png\)/);assert.match(curator,/\| Object name \|[^\n]*\*\*Description:\*\* Identify the object[^\n]*\*\*Field:\*\*[^\n]*Editable[^\n]*Required[^\n]*Reject blank entries[^\n]*See rule: Name requirement/);assert.match(curator,/\| Name report column \|[^\n]*Read only/);assert.match(curator,/\| Object table \|[^\n]*Object name[^\n]*Accession code/);assert.match(curator,/\| Accession code \|[^\n]*Optional/);assert.match(reviewer,/\| Object name \|[^\n]*Read-only/);assert.equal((curator.match(/Document the record/g)||[]).length,1);assert.equal((curator.match(/A name is required/g)||[]).length,1);assert.match(curator,/Exception \(Description section\):\*\* Explain an empty description/);assert.doesNotMatch(curator,/Not specified|Visibility: Always/);
 assert.match(reviewer,/\[Shared page: Object editor — Draft state\]\(#basePage\)/);assert.match(reviewer,/Consequence: Review routing is unknown/);assert.match(system,/Object record/);assert.match(system,/\*\*Open points:\*\*[^\n]*\*\*Permission:\*\* Approval owner unknown[^\n]*\*\*Audit:\*\* Audit owner unknown/);assert.match(html,/<figcaption>Editor concept<\/figcaption>/);assert.match(html,/<h3 id="curatorChapter">Curator<\/h3>/);assert.match(html,/<th scope="col">Element<\/th><th scope="col">Rule<\/th>/);assert.match(html,/<table class="product-feature-list"><colgroup>/);
 get(m,'nameRule').rule.effect='A descriptive name is mandatory';assert.match(renderProductMarkdown(composeProductDocument(m)),/A descriptive name is mandatory/);
 assert.throws(()=>composeProductDocument(m,{resources:{prototypes:{page:[{src:'https://example.invalid/image.png',caption:'Unapproved'}]}}}),/approved local asset/);
