test('typed rule cells preserve structured fields, scoped exceptions and operation facts without parsing prose',()=>{
 const m=museum(),rule=get(m,'nameRule'),control=get(m,'nameControl'),action=get(m,'index');get(m,'artifact').detail.unit='labels';rule.rule.condition={field:'artifact',op:'ne',value:'A; B: C'};rule.rule.effect='Keep A: B; do not split';rule.gap='Confirm the threshold: after review; not before';rule.rule.exceptions[1].condition={field:'accession',op:'eq',value:'X; Y'};control.detail.behavior='Warn: save; <script>bad</script> | next';action.refs.push(ref('field','artifact','field'),ref('field','accession','field'));assert.deepEqual(errors(m),[]);
 const ir=composeProductDocument(m),tables=ir.nodes.filter(n=>n.type==='table'),ruleRow=tables.flatMap(t=>t.rows).find(r=>r[0]==='Name requirement'),actionRow=tables.flatMap(t=>t.rows).find(r=>r[0]==='Index object');assert.equal(ruleRow[1].type,'structured');assert.deepEqual(ruleRow[1].groups.Field.map(x=>x.title),['Object name','Accession code']);assert.ok(ruleRow[1].groups.Exceptions.some(x=>x.text.includes('X; Y')));assert.ok(ruleRow[1].groups['Open points'].some(x=>x.text==='Confirm the threshold: after review; not before'));assert.ok(!JSON.stringify(ruleRow[1]).includes('Search text'));assert.deepEqual(actionRow[1].groups.Field.map(x=>x.title),['Object name','Accession code']);assert.ok(actionRow[1].groups.Operation.some(x=>x.title==='Input'&&x.text==='Object record'));assert.ok(actionRow[1].groups['Open points'].some(x=>x.title==='Permission'&&x.text==='Approval owner unknown'));
 const md=renderProductMarkdown(ir),html=renderProductHtml(ir),line=md.split('\n').find(x=>x.startsWith('| Name requirement |'));assert.match(line,/\*\*Description:\*\* Require a name/);assert.match(line,/\*\*Field:\*\*<br>• \*\*Object name:\*\*/);assert.match(line,/\*\*Behavior \/ Conditions:\*\*[^\n]*A; B: C/);assert.match(line,/Keep A: B; do not split/);assert.match(line,/\*\*Exceptions:\*\*[^\n]*X; Y/);assert.match(md,/Warn: save; &lt;script&gt;bad&lt;\/script&gt; \\\| next/);assert.match(html,/<div class="product-cell"><p><strong>Description:<\/strong>/);assert.match(html,/<strong>Field:<\/strong><\/p><ul><li><strong>Object name:<\/strong>/);assert.match(html,/Warn: save; &lt;script&gt;bad&lt;\/script&gt; \| next/);assert.doesNotMatch(html,/<script>bad<\/script>/);
});

