function publicPolicy(model){
 const permitted=model.objects.filter(o=>o.type!=='source'), aliases=new Map(permitted.map((o,i)=>[o.id,`pubObject${i+1}`]));
 const objects=Object.fromEntries(permitted.map(o=>[o.id,{id:aliases.get(o.id),title:`Public ${o.type} ${aliases.get(o.id)}`,purpose:`Approved purpose ${aliases.get(o.id)}`,fields:[...Object.keys(o.detail).map(k=>`detail.${k}`),...['rule','gap','priority'].filter(k=>Object.hasOwn(o,k))],...(o.parent?{parent:true}:{}),relations:(o.refs||[]).filter(r=>r.type!=='source').map(r=>({relation:r.relation,target:r.target}))}]));
 const plan=structuredClone(model.profile.productDocument);let serial=0;for(const s of plan.services){s.module='Public collections';s.overview='Approved overview';for(const f of s.features){f.subModule='Public section';if(f.note)f.note='Approved note';}for(const w of s.workflows)w.caption='Approved overall workflow';const caseIds=new Map(s.useCases.map(u=>[u.id,`pubCase${++serial}`])),pageIds=new Map(s.useCases.flatMap(u=>u.pages.map(p=>[p.id,`pubPage${++serial}`])));for(const c of s.roleChapters){c.id=`pubRoleChapter${++serial}`;c.useCases=c.useCases.map(id=>caseIds.get(id));for(const w of c.workflows||[])w.caption='Approved role workflow';}for(const u of s.useCases){u.id=caseIds.get(u.id);u.title=`Approved task ${++serial}`;u.story='I need to perform this task so that the record can proceed.';u.postconditions='Approved task outcome.';for(const w of u.workflows||[])w.caption='Approved task workflow';for(const p of u.pages){p.id=pageIds.get(p.id);if(p.reuse)p.reuse=pageIds.get(p.reuse);p.entry='Open the approved page.';}for(const e of u.edgeCases)if(e.note)e.note='Approved exception note.';}}
 const view=model.nativeViews[0],viewId=view.id,lanes=Object.fromEntries(view.spec.lanes.map((l,i)=>[l.id,{id:`publicLane${i}`,label:`Approved operator ${i}`} ])),nodes=Object.fromEntries(view.spec.nodes.map((n,i)=>[n.id,{id:`publicNode${i}`,label:`Approved action ${i}`} ]));return {version:1,components:{all:'Public scope'},objects,productDocument:plan,views:{[viewId]:{id:'publicFlow',title:'Public workflow',caption:'Public workflow',context:'Approved workflow context',version:'1',sourceVersion:'1',service:'service',lanes,nodes}}};
}

