test('applied review flags remain visible beside affected rules and owning pages in both audiences',t=>{
 const dir=fs.mkdtempSync(path.join(os.tmpdir(),'product-review-'));t.after(()=>fs.rmSync(dir,{recursive:true,force:true}));const model=museum();model.workspaceId='12345678-1234-4234-8234-123456789abc';get(model,'nameRule').status='customer-confirmed';get(model,'page').status='customer-confirmed';get(model,'nameRule').rule.condition={field:'artifact',op:'ne',value:''};const policy=publicPolicy(model),input=path.join(dir,'model.json'),policyFile=path.join(dir,'policy.json'),historyFile=path.join(dir,'history.json');const write=(file,value)=>fs.writeFileSync(file,JSON.stringify(value));write(input,model);write(policyFile,policy);const cli=path.resolve('archify/bin/archify.mjs');const run=(...args)=>{const p=spawnSync(process.execPath,[cli,'prd',...args,'--json'],{cwd:dir,encoding:'utf8',maxBuffer:32*1024*1024});assert.equal(p.stderr,'');return {status:p.status,...JSON.parse(p.stdout)};};const history=audience=>({schemaVersion:1,service:'service',audience,entries:[{version:'1',date:'2026-01-02',summary:'Initial product'}]});const histories={internal:history('internal'),client:history('client')};const exportService=(file,audience,name,base)=>{write(historyFile,histories[audience]);return run('export',file,'-o',path.join(dir,name),'--service','service','--service-history',historyFile,'--markdown-only','--audience',audience,...(audience==='client'?['--disclosure',policyFile]:[]),...(base?['--incremental-from',path.join(dir,base)]:[]));};for(const audience of ['internal','client']){const initial=exportService(input,audience,`${audience}-before`);assert.equal(initial.status,0,JSON.stringify(initial));}
 const compiled=run('compile',input,'-o',path.join(dir,'compiled.json'));assert.equal(compiled.status,0,JSON.stringify(compiled));const commentFile=path.join(dir,'comments.json'),store=path.join(dir,'store.json');write(commentFile,{kind:'archify-prd-feedback',schemaVersion:1,workspaceId:model.workspaceId,comments:[{id:'fieldComment',objectId:'artifact',baseRevision:compiled.revision,quoteSnapshot:{path:'/purpose',text:'Identify the object'},author:'Reviewer',time:'2026-01-03T00:00:00Z',body:'Clarify the field unit.',state:'open'}]});const imported=run('feedback','import',commentFile,'--model',input,'-o',store);assert.equal(imported.status,0,JSON.stringify(imported));const request=path.join(dir,'request.json'),proposal=path.join(dir,'proposal.json'),updated=path.join(dir,'updated.json');write(request,{kind:'archify-prd-change-request',schemaVersion:1,workspaceId:model.workspaceId,proposalId:'PRIVATE_REVIEW_PROPOSAL',baseRevision:compiled.revision,storeRevision:imported.revision,objectId:'artifact',operation:'replace',path:'/detail/unit',oldValue:'Not specified',oldHash:createHash('sha256').update(JSON.stringify('Not specified')).digest('hex'),newValue:'catalog label',commentIds:['fieldComment']});const proposed=run('feedback','propose',request,'--model',input,'--store',store,'--expect-store',imported.revision,'-o',proposal);assert.equal(proposed.status,0,JSON.stringify(proposed));const applied=run('feedback','apply',proposal,'--model',input,'--store',store,'--expect-store',imported.revision,'-o',updated);assert.equal(applied.status,0,JSON.stringify(applied));const revised=JSON.parse(fs.readFileSync(updated));assert.ok(get(revised,'nameRule').review?.causes?.length,JSON.stringify(applied));assert.ok(get(revised,'page').review?.summaryCauses?.length,JSON.stringify(applied));assert.equal(get(revised,'nameRule').status,'customer-confirmed');assert.equal(get(revised,'page').status,'customer-confirmed');
 for(const audience of ['internal','client']){const noHistory=exportService(updated,audience,`${audience}-no-history`,`${audience}-before`);assert.equal(noHistory.status,1);histories[audience].entries.push({version:'2',date:'2026-01-03',summary:'Clarify the field unit'});const result=exportService(updated,audience,`${audience}-after`,`${audience}-before`);assert.equal(result.status,0,JSON.stringify(result));assert.ok(result.cache.componentsReused>0);assert.ok(result.cache.componentsRendered>0);const text=fs.readFileSync(path.join(dir,`${audience}-after`,'README.md'),'utf8'),ruleTitle=audience==='internal'?'Name requirement':policy.objects.nameRule.title,pageTitle=audience==='internal'?'Object editor':policy.objects.page.title;const ruleLine=text.split('\n').find(line=>line.includes(ruleTitle)&&line.includes('Status: customer-confirmed'));assert.ok(ruleLine?.includes('Technical review needed'),ruleLine);const pageStart=text.indexOf(pageTitle),pageText=text.slice(pageStart,pageStart+1000);assert.match(pageText,/Status: customer-confirmed; Technical review needed/);if(audience==='client'){assert.doesNotMatch(text,/PRIVATE_REVIEW_PROPOSAL/);const append=fs.readFileSync(path.join(dir,'client-after','appendix.md'),'utf8');assert.doesNotMatch(append,/PRIVATE_REVIEW_PROPOSAL/);}const warm=exportService(updated,audience,`${audience}-warm`,`${audience}-after`);assert.equal(warm.status,0,JSON.stringify(warm));assert.equal(warm.cache.componentsRendered,0);}
});

test('product HTML, PDF and reader print use the same readable scoped typography',async t=>{
 if(!process.env.ARCHIFY_CHROME){t.skip('Set ARCHIFY_CHROME to a sandboxed Chromium executable.');return;}
 const dir=fs.mkdtempSync(path.join(os.tmpdir(),'product-pdf-'));t.after(()=>fs.rmSync(dir,{recursive:true,force:true}));const input=path.join(dir,'model.json');fs.writeFileSync(input,JSON.stringify(museum()));const cli=path.resolve('archify/bin/archify.mjs'),out=path.join(dir,'out'),reader=path.join(dir,'reader.html');const run=args=>spawnSync(process.execPath,[cli,'prd',...args,'--json'],{cwd:dir,encoding:'utf8',timeout:60000,maxBuffer:32*1024*1024});const p=run(['export',input,'-o',out,'--pdf']);assert.equal(p.stderr,'');assert.equal(p.status,0,p.stdout);assert.equal(fs.readFileSync(path.join(out,'document.pdf')).subarray(0,5).toString(),'%PDF-');assert.match(fs.readFileSync(path.join(out,'index.html'),'utf8'),/Role workflow/);assert.match(fs.readFileSync(path.join(out,'README.md'),'utf8'),/Authored revision history not provided/);const built=run(['build',input,'-o',reader]);assert.equal(built.status,0,built.stdout+built.stderr);
 const browser=new ChromeVisualBrowser(process.env.ARCHIFY_CHROME);try{const session=await browser.sessionPromise,send=(method,params={})=>browser.cdp.send(method,params,session),evaluate=async expression=>{const r=await send('Runtime.evaluate',{expression,returnByValue:true});assert.equal(r.exceptionDetails,undefined,r.exceptionDetails?.exception?.description);return r.result.value;},open=async file=>{const url=pathToFileURL(file).href;await send('Page.navigate',{url});for(let i=0;i<200;i++){if(await evaluate(`location.href===${JSON.stringify(url)}&&document.readyState==='complete'`))return;await new Promise(r=>setTimeout(r,25));}assert.fail('Timed out loading product document');};await send('Emulation.setDeviceMetricsOverride',{width:700,height:900,deviceScaleFactor:1,mobile:false});
 const measure=`(()=>{const root=document.querySelector('.product-document'),table=root.querySelector('.product-feature-list'),head=[...table.querySelectorAll('th')],style=getComputedStyle(table),h5=root.querySelector('h5'),rows=[...root.querySelectorAll('table:not(.product-feature-list)')];return {bodySize:getComputedStyle(root).fontSize,taskSize:getComputedStyle(h5).fontSize,tableSize:style.fontSize,wordBreak:getComputedStyle(head[5]).wordBreak,wrap:getComputedStyle(head[5]).overflowWrap,columns:head.map(h=>Math.round(h.getBoundingClientRect().width)),headerLines:head.map(h=>{const r=document.createRange();r.selectNodeContents(h);return r.getClientRects().length}),fieldTable:rows.some(t=>t.textContent.includes('Object name')&&t.textContent.includes('Name requirement')),history:root.textContent.includes('Authored revision history not provided.')};})()`;
 await open(path.join(out,'index.html'));await send('Emulation.setEmulatedMedia',{media:'print'});const exported=await evaluate(measure);assert.equal(exported.bodySize,'16px');assert.ok(parseFloat(exported.taskSize)>=parseFloat(exported.bodySize));assert.equal(exported.tableSize,'12.6667px');assert.equal(exported.wordBreak,'normal');assert.equal(exported.wrap,'break-word');assert.equal(exported.headerLines[4],1);assert.equal(exported.headerLines[5],1);assert.ok(exported.columns[5]>exported.columns[4]);assert.ok(exported.fieldTable&&exported.history);
 await send('Emulation.setEmulatedMedia',{media:'screen'});await open(reader);const screen=await evaluate(`({print:getComputedStyle(document.querySelector('#print-document')).display,ui:getComputedStyle(document.querySelector('#layout')).display,body:getComputedStyle(document.documentElement).fontSize})`);assert.equal(screen.print,'none');assert.notEqual(screen.ui,'none');assert.equal(screen.body,'15px');await send('Emulation.setEmulatedMedia',{media:'print'});const printed=await evaluate(measure);assert.deepEqual(printed,exported);
 }finally{await browser.close();}
});

