 get(model,'nameRule').rule.effect='An identifying name is mandatory';history.entries.push({version:'2',date:'2026-01-03',summary:'Revise the naming rule'});save();const changed=exportService('changed','--incremental-from',path.join(dir,'first'));assert.equal(changed.status,0,JSON.stringify(changed));assert.ok(changed.cache.componentsReused>0);assert.ok(changed.cache.componentsRendered>0);assert.match(read('changed','README.md').toString(),/An identifying name is mandatory/);
 model.nativeViews[0].spec.nodes[0].label='Describe the artifact';history.entries.push({version:'3',date:'2026-01-04',summary:'Revise workflow'});save();const flow=exportService('flow','--incremental-from',path.join(dir,'changed'));assert.equal(flow.status,0,JSON.stringify(flow));assert.ok(flow.cache.resourcesRendered>0);assert.ok(flow.cache.componentsReused>0);assert.match(read('flow','assets/native-flow.svg').toString(),/Describe the artifact/);
