 model.objects.push(object('searchRule','rule','Search requirement','Require a search term',{}, {rule:{scope:['search'],condition:{constant:true},effect:'Search terms must be meaningful',unit:'Not specified',precision:'Not specified',time:'At search'}}));save();const unplacedRule=exportService('unplaced-rule','--incremental-from',path.join(dir,'expanded'));assert.equal(unplacedRule.status,1);assert.ok(unplacedRule.diagnostics.some(d=>d.evidence?.id==='searchRule'));svc(model).useCases[0].pages[1].items.push('searchRule');history.entries.push({version:'5a',date:'2026-01-06',summary:'Document search rule'});save();const rule=exportService('rule','--incremental-from',path.join(dir,'expanded'));assert.equal(rule.status,0,JSON.stringify(rule));assert.ok(rule.cache.componentsReused>0);assert.match(read('rule','README.md').toString(),/Search terms must be meaningful/);
